import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchJobs } from "../Features/JobSlice";
import axios from "axios";
import "../Styles/CompanyJobs.css";

const CompanyJobs = () => {
  const dispatch = useDispatch();
  const { jobs } = useSelector((state) => state.jobs);

  const [editingJob, setEditingJob] = useState(null);
  const [editedData, setEditedData] = useState({});

  // Get logged-in company info
  const loggedCompany = JSON.parse(localStorage.getItem("loggedUser"));
  const companyEmail = loggedCompany?.email;

  // Fetch jobs from database
  useEffect(() => {
    dispatch(fetchJobs());
  }, [dispatch]);

  // Filter jobs for the current company only
  const companyJobs = jobs.filter((job) => job.organization === companyEmail);

  // Delete job by ID (from MongoDB)
  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:3001/jobs/${id}`);
      alert("Job deleted successfully");
      dispatch(fetchJobs());
    } catch (err) {
      alert("Failed to delete job");
    }
  };

  // Save edited job changes (update in MongoDB)
  const handleSave = async () => {
    try {
      await axios.put(
        `http://localhost:3001/jobs/${editingJob._id}`,
        editedData
      );
      alert("Job updated successfully");
      setEditingJob(null);
      dispatch(fetchJobs());
    } catch (err) {
      alert("Failed to update job");
    }
  };

  return (
    <div className="companyjobs-page">
      <h1 className="companyjobs-title">
        My <span className="accent">Posted Jobs</span>
      </h1>

      {companyJobs.length === 0 ? (
        <p className="no-jobs">No jobs posted yet.</p>
      ) : (
        companyJobs.map((job) => (
          <div key={job._id} className="job-card">
            {editingJob?._id === job._id ? (
              <>
                <label>Job Title</label>
                <input
                  type="text"
                  value={editedData.jobTitle}
                  onChange={(e) =>
                    setEditedData({ ...editedData, jobTitle: e.target.value })
                  }
                />

                <label>Description</label>
                <textarea
                  value={editedData.description}
                  onChange={(e) =>
                    setEditedData({
                      ...editedData,
                      description: e.target.value,
                    })
                  }
                />

                <label>Skills</label>
                <input
                  type="text"
                  value={editedData.skills}
                  onChange={(e) =>
                    setEditedData({ ...editedData, skills: e.target.value })
                  }
                />

                <div className="edit-buttons">
                  <button onClick={handleSave} className="btn-save">
                    Save
                  </button>
                  <button
                    onClick={() => setEditingJob(null)}
                    className="btn-cancel"
                  >
                    Cancel
                  </button>
                </div>
              </>
            ) : (
              <>
                <div className="job-header">
                  <h3>{job.jobTitle}</h3>
                  <span className="rate">
                    {job.rate} OMR · {job.rateType}
                  </span>
                </div>

                <p className="org-name">{job.organization}</p>
                <p className="desc">{job.description}</p>
                <p className="skills">Skills: {job.skills}</p>

                <div className="job-actions">
                  <button
                    className="btn-edit"
                    onClick={() => {
                      setEditingJob(job);
                      setEditedData(job);
                    }}
                  >
                    Edit
                  </button>

                  <button
                    className="btn-delete"
                    onClick={() => handleDelete(job._id)}
                  >
                    Delete
                  </button>
                </div>
              </>
            )}
          </div>
        ))
      )}
    </div>
  );
};

export default CompanyJobs;
